// Routing benchmark corpus for the Needle 2 repository-intelligence gateway
// (spec §47-49, §128-129 of specs/banyancode_needle2_universal_repository_intelligence_architecture.md).
//
// Standalone dataset: consumed by later phases (rules router, Needle shadow,
// router-benchmark). This file must stay free of runtime/gateway imports so it
// can be loaded by any evaluator. Each case records a tool call (read/grep/glob)
// with its arguments, the original user request when it disambiguates intent
// (spec §21), and the route a correct router must choose.
//
// Route semantics (spec §13): DIRECT_* = execute the original tool unchanged;
// SYMBOL_SEARCH / REFERENCES / CALLERS / CALLEES / DEPENDENTS / IMPORTS /
// IMPLEMENTATIONS / EXTENSIONS / IMPACT / STRUCTURAL / ARCHITECTURE / OWNERSHIP
// = rewrite into the corresponding repository-intelligence operation;
// HYBRID = combine multiple routes.
//
// Hard negatives (category "hard-negative", spec §48/§128/§129) must all route
// DIRECT_*: documentation paths and explicit phrase searches override
// relationship phrasing. Ambiguous cases carry a `note` explaining which
// routes were plausible and why the direct fallback is correct.

export interface RoutingCase {
  id: string
  toolName: "read" | "grep" | "glob"
  arguments: Record<string, unknown>
  userRequest?: string
  expectedRoute:
    | "DIRECT_READ"
    | "DIRECT_SEARCH"
    | "DIRECT_GLOB"
    | "SYMBOL_SEARCH"
    | "REFERENCES"
    | "CALLERS"
    | "CALLEES"
    | "DEPENDENTS"
    | "IMPORTS"
    | "IMPLEMENTATIONS"
    | "EXTENSIONS"
    | "IMPACT"
    | "STRUCTURAL"
    | "ARCHITECTURE"
    | "OWNERSHIP"
    | "HYBRID"
  category:
    | "content"
    | "lexical-search"
    | "symbol"
    | "relationships"
    | "structural"
    | "architecture"
    | "ambiguous"
    | "hard-negative"
  note?: string
}

